const sweepTroubleshootingSessions = `-- name: SweepTroubleshootingSessions :many
UPDATE troubleshooting_sessions SET state = 'closed',closed_at = now(),close_reason = 'expired',ticket_hash = NULL,browser_session_hash = NULL
WHERE state <> 'closed' AND (deadline_at <= now() - interval '1 minute' OR (state = 'offered' AND ticket_expires_at <= now()))
RETURNING workspace_id,id,actor_id
`

type SweepTroubleshootingSessionsRow struct {
	WorkspaceID uuid.UUID `json:"workspace_id"`
	ID          uuid.UUID `json:"id"`
	ActorID     uuid.UUID `json:"actor_id"`
}

// unscoped: an installation-wide sweeper ends expired sessions in every workspace.
func (q *Queries) SweepTroubleshootingSessions(ctx context.Context) ([]SweepTroubleshootingSessionsRow, error) {
	rows, err := q.db.Query(ctx, sweepTroubleshootingSessions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SweepTroubleshootingSessionsRow{}
	for rows.Next() {
		var i SweepTroubleshootingSessionsRow
		if err := rows.Scan(&i.WorkspaceID, &i.ID, &i.ActorID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const troubleshootingAdmissionCounts = `-- name: TroubleshootingAdmissionCounts :one
SELECT
 count(*) AS installation,
 count(*) FILTER (WHERE workspace_id = $1) AS workspace,
 count(*) FILTER (WHERE actor_id = $2) AS actor,
 count(*) FILTER (WHERE workspace_id = $1 AND server_id = $3) AS server,
 count(*) FILTER (WHERE workspace_id = $1 AND server_id = $3 AND environment_id = $4 AND application_id = $5 AND instance = $6) AS target
FROM troubleshooting_sessions
WHERE state <> 'closed' AND deadline_at > now() AND (state <> 'offered' OR ticket_expires_at > now())
`

type TroubleshootingAdmissionCountsParams struct {
	WorkspaceID   uuid.UUID `json:"workspace_id"`
	ActorID       uuid.UUID `json:"actor_id"`
	ServerID      uuid.UUID `json:"server_id"`
	EnvironmentID uuid.UUID `json:"environment_id"`
	ApplicationID uuid.UUID `json:"application_id"`
	Instance      int32     `json:"instance"`
}

type TroubleshootingAdmissionCountsRow struct {
	Installation int64 `json:"installation"`
	Workspace    int64 `json:"workspace"`
	Actor        int64 `json:"actor"`
	Server       int64 `json:"server"`
	Target       int64 `json:"target"`
}

// unscoped: the installation and per-actor limits span workspaces; each result is only a count.
func (q *Queries) TroubleshootingAdmissionCounts(ctx context.Context, arg TroubleshootingAdmissionCountsParams) (TroubleshootingAdmissionCountsRow, error) {
	row := q.db.QueryRow(ctx, troubleshootingAdmissionCounts,
		arg.WorkspaceID,
		arg.ActorID,
		arg.ServerID,
		arg.EnvironmentID,
		arg.ApplicationID,
		arg.Instance,
	)
	var i TroubleshootingAdmissionCountsRow
	err := row.Scan(
		&i.Installation,
		&i.Workspace,
		&i.Actor,
		&i.Server,
		&i.Target,
	)
	return i, err
}

const troubleshootingEnvironment = `-- name: TroubleshootingEnvironment :one
SELECT e.applied_revision_id,d.server_id AS primary_server_id,r.specification
FROM environments e
JOIN deployment_units d ON d.workspace_id = e.workspace_id AND d.environment_id = e.id AND d.primary_unit
LEFT JOIN specification_revisions r ON r.workspace_id = e.workspace_id AND r.environment_id = e.id AND r.id = e.applied_revision_id
WHERE e.workspace_id = $1 AND e.project_id = $2 AND e.id = $3
`

